import { z } from 'zod'

/**
 * Contract of the agent knowledge bundle (`agent-docs/`) generated by
 * `scripts/generate-agent-docs.ts` and shipped in the relizy package.
 */
export const SCHEMA_VERSION = 1

export const docCategories = ['guide', 'config', 'cli', 'commitlint', 'api'] as const

export type DocCategory = typeof docCategories[number]

export const docEntrySchema = z.object({
  /** Path of the page without extension, e.g. `guide/version-groups` */
  id: z.string(),
  category: z.enum(docCategories),
  title: z.string(),
  description: z.string(),
  keywords: z.array(z.string()),
  headings: z.array(z.string()),
  /** File of the page, relative to the bundle */
  file: z.string(),
  url: z.string(),
  chars: z.number(),
})

export const configOptionSchema = z.object({
  /** Dotted path, `[]` for the items of an array: `monorepo.groups[].versionMode` */
  path: z.string(),
  type: z.string(),
  /** Values accepted by the type when it hides them behind an alias: `["\"unified\"", "\"selective\"", "\"independent\""]` for `VersionMode` */
  values: z.array(z.string()).optional(),
  description: z.string(),
  /** `@default` of the JSDoc */
  default: z.string().optional(),
  deprecated: z.string().optional(),
  see: z.string().optional(),
  /** Doc page of the option */
  docId: z.string(),
})

export const manifestSchema = z.object({
  schemaVersion: z.literal(SCHEMA_VERSION),
  name: z.literal('relizy'),
  version: z.string(),
  homepage: z.string(),
  docs: z.array(docEntrySchema),
  config: z.array(configOptionSchema),
})

export type DocEntry = z.infer<typeof docEntrySchema>
export type ConfigOption = z.infer<typeof configOptionSchema>
export type Manifest = z.infer<typeof manifestSchema>
